// AEGIS CDC contract: gray_src  (crossing x_7d5121c5)
// Source-domain guarantees for a Gray-coded pointer that crosses to another
// clock domain (async FIFO read/write pointers, Gray counters).
// Generated by gen_cdc_props.py -- do not edit by hand.
//
//  [G1] at most one bit of the crossing pointer changes per source clock.
//       This is what makes a multi-bit Gray bus safe to sample asynchronously.
//  [G2] the pointer only holds or advances by +1 in Gray sequence (mod 2^W).
//       Rules out "one-bit" jumps that are not legal Gray steps, which would
//       still corrupt the far side's full/empty computation.
module aegis_chk_gray_src_x_7d5121c5 #(parameter W = 2) (
  input wire         clk,
  input wire         rst_act,
  input wire [W-1:0] ptr
);
  // ---- common harness (generated) ---------------------------------------
  // f_ok = clock edges since this domain's reset was released (saturating).
  // Every check is gated on f_ok so nothing is judged during or straight
  // after reset.
  reg [7:0] f_ok = 8'd0;
  always @(posedge clk)
    if (rst_act)              f_ok <= 8'd0;
    else if (f_ok != 8'hff)   f_ok <= f_ok + 8'd1;
  reg [W-1:0] past_ptr;
  always @(posedge clk) past_ptr <= ptr;

  function [W-1:0] g2b;
    input [W-1:0] g;
    integer i;
    begin
      g2b[W-1] = g[W-1];
      for (i = W-2; i >= 0; i = i - 1) g2b[i] = g2b[i+1] ^ g[i];
    end
  endfunction

  wire [W-1:0] diff   = ptr ^ past_ptr;
  wire [W-1:0] b_now  = g2b(ptr);
  wire [W-1:0] b_past = g2b(past_ptr);
  wire         f_chk  = (f_ok >= 8'd1) && !rst_act;

  always @(*) if (f_chk) assert ((diff & (diff - 1'b1)) == 0);                   // [G1]
  always @(*) if (f_chk) assert ((b_now == b_past) || (b_now == b_past + 1'b1)); // [G2]
endmodule
